CREATE TABLE washing_machines (
    id INTEGER PRIMARY KEY,
    name TEXT,
    brand TEXT,
    type TEXT,
    size TEXT,
    price INTEGER,
    color TEXT,
    warranty TEXT,
    energy_rating TEXT,
    features TEXT
);

CREATE TABLE fridges (
    id INTEGER PRIMARY KEY,
    name TEXT,
    brand TEXT,
    type TEXT,
    size TEXT,
    price INTEGER,
    color TEXT,
    warranty TEXT,
    energy_rating TEXT,
    features TEXT
);

CREATE TABLE tvs (
    id INTEGER PRIMARY KEY,
    name TEXT,
    brand TEXT,
    type TEXT,
    size TEXT,
    price INTEGER,
    color TEXT,
    warranty TEXT,
    resolution TEXT,
    features TEXT
);

CREATE TABLE dishwashers (
